SELECT /*LGUTLC00020.retrieveDebuggingList*/ lds.debug_log_setup_id ,lds.debug_target_type_code AS debug_type_code ,DECODE(lds.debug_target_type_code,'USER',TO_CHAR(lds.application_user_id),lds.program_id) AS debug_scope_id ,DECODE(lds.debug_target_type_code,'USER',lds.full_name_local,lds.program_name) AS debug_scope_name ,lds.use_flag use_flag ,lds.created_by ,lds.created_by_name ,lds.creation_date FROM lgcom_debug_setup_m_v lds WHERE 1 = 1
AND lds.full_name_local = #{debugScopeName}
AND lds.program_name = #{debugScopeName}
AND debug_target_type_code = #{debugTypeCode}
AND use_flag = #{useFlag}
ORDER BY 2, 4

mapper.update:
/*LGUTLC00020.updateDebuggingList*/
	UPDATE lgcom_debug_setup_m
	   SET use_flag = #{useFlag}
	     , last_updated_by = #{sessionUserId}
	     , last_update_date = SYSDATE
	 WHERE debug_log_setup_id = #{debugLogSetupId}

